=Generate a respectful, progressive 3-touch problem-first outreach sequence and a SuperDocs in-document refactor prompt for:
Organization: {{ $json.organization_name }}
Lead Role: {{ $json.recipient_role }}
Document Scope: {{ $json.active_document_type }} ({{ $json.document_page_count }} Pages)
Core Tech Stack: {{ $json.core_parameters.model_type }}

Strict Rules:
1. Never claim to have scraped their private draft.
2. Open with the shared pain point: editing existing 30+ page documents with ChatGPT requires messy copy-pasting into Word, breaking tables and citations.
3. Position SuperDocs as 'Cursor for documents' (in-document multi-section editing with native red/green diff review).
4. Include an in-document prompt snippet and diff preview.

parameters.jsCode:
// Automated 4-Dimension Quality Gate Node
const items = $input.all();
const outputResults = [];
const MIN_PASS_SCORE = 85.0;

for (const item of items) {
  const data = item.json;
  const text = data.generated_content || JSON.stringify(data);
  const org = data.organization_name || '';

  let score = 0;
  const breakdown = {};

  // 1. Technical Specificity (0-25)
  const hasOrg = text.toLowerCase().includes(org.toLowerCase());
  breakdown.technical_specificity = hasOrg ? 25 : 15;
  score += breakdown.technical_specificity;

  // 2. Taste & Tone (0-25) - Penalize generic sales hype
  const hasHype = /best-in-class|revolutionary|game-changing|act now/i.test(text);
  breakdown.taste_and_tone = hasHype ? 10 : 25;
  score += breakdown.taste_and_tone;

  // 3. Rails Compliance (0-25) - No spreadsheet outputs, strict privacy
  const violatesSpreadsheetRail = text.toLowerCase().includes('spreadsheet output');
  breakdown.rails_compliance = violatesSpreadsheetRail ? 0 : 25;
  score += breakdown.rails_compliance;

  // 4. Syntax & Diff Integrity (0-25)
  const hasDiffOrTable = text.includes('```diff') || text.includes('|');
  breakdown.syntax_integrity = hasDiffOrTable ? 25 : 15;
  score += breakdown.syntax_integrity;

  const passesGate = score >= MIN_PASS_SCORE;

  outputResults.push({
    json: {
      ...data,
      quality_score: score,
      score_breakdown: breakdown,
      gate_status: passesGate ? 'PASSED_QA_GATE' : 'QUARANTINED',
      staged_for_human_gate_1: passesGate
    }
  });
}

return outputResults;
